package batch

import (
	"errors"
	"time"
)

// Run processes jobs in batches of size n, retrying a failed batch up to retries times.
func Run(jobs []string, n, retries int, do func([]string) error) error {
	for i := 0; i < len(jobs); i += n {
		end := i + n
		if end > len(jobs) {
			end = len(jobs)
		}
		var err error
		for a := 0; a <= retries; a++ {
			if err = do(jobs[i:end]); err == nil {
				break
			}
			time.Sleep(time.Duration(a+1) * 50 * time.Millisecond)
		}
		if err != nil {
			return errors.Join(errors.New("batch failed"), err)
		}
	}
	return nil
}
